<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Solicitud de contrato | Dorantes</title>
    <style>
        :root{--ink:#16324f;--muted:#5f7183;--line:#d8e1e8;--soft:#f4f7f9;--brand:#155e75;--brand-dark:#0f4c5c;--danger:#a32d2d}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:#1f2d3d;font:16px/1.45 Arial,Helvetica,sans-serif}.contract-shell{max-width:900px;margin:0 auto;padding:32px 18px 48px}.contract-card{background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 12px 30px rgba(22,50,79,.08);padding:30px}.contract-header{margin-bottom:24px}h1{color:var(--ink);font-size:28px;line-height:1.2;margin:0 0 8px}h2{color:var(--ink);font-size:21px;margin:0 0 20px}.contract-subtitle,.helper{color:var(--muted);margin:0}.stepper{display:flex;flex-wrap:wrap;gap:7px;margin:20px 0 26px}.stepper a{border:1px solid var(--line);border-radius:999px;color:#38536b;font-size:13px;padding:7px 11px;text-decoration:none;background:#fff}.stepper a[aria-current="step"]{background:var(--brand);border-color:var(--brand);color:#fff;font-weight:700}.alert,.success{border-left:4px solid;border-radius:6px;margin:0 0 20px;padding:12px 14px}.alert{background:#fff0f0;border-color:var(--danger);color:#7b1e1e}.success{background:#ecfdf5;border-color:#047857;color:#065f46}.field-grid{display:grid;gap:16px;grid-template-columns:repeat(2,minmax(0,1fr))}.field-wide{grid-column:1/-1}label{color:#30485d;display:block;font-size:14px;font-weight:700}input,select{appearance:none;background:#fff;border:1px solid #b8c7d3;border-radius:8px;color:#1f2d3d;display:block;font:inherit;margin-top:6px;min-height:42px;padding:9px 11px;width:100%}input[type="checkbox"]{appearance:auto;display:inline-block;min-height:auto;margin:0 7px 0 0;padding:0;width:auto}input:focus,select:focus{border-color:var(--brand);box-shadow:0 0 0 3px rgba(21,94,117,.16);outline:0}.section-heading{border-bottom:1px solid var(--line);margin:0 0 20px;padding-bottom:10px}.choice-list{display:grid;gap:10px;grid-template-columns:repeat(2,minmax(0,1fr))}.choice{align-items:center;border:1px solid var(--line);border-radius:8px;color:#30485d;display:flex;font-weight:400;padding:11px}.actions{align-items:center;display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-end;margin-top:28px}button{border:1px solid transparent;border-radius:8px;cursor:pointer;font:inherit;font-weight:700;min-height:42px;padding:10px 16px}.button-secondary{background:#fff;border-color:#8aa0b1;color:#29485e}.button-primary{background:var(--brand);color:#fff}.button-primary:hover{background:var(--brand-dark)}.summary{display:grid;gap:16px;margin:0}.summary div{border-bottom:1px solid var(--line);padding-bottom:14px}.summary dt{color:var(--ink);font-size:14px;font-weight:700}.summary dd{margin:4px 0 0}.is-hidden{display:none!important}.contract-party>.grid,.contract-party fieldset{margin-top:16px}.contract-party fieldset{background:#f8fafb;border:1px solid var(--line);border-radius:10px;padding:18px}@media(max-width:640px){.contract-shell{padding:20px 12px 34px}.contract-card{border-radius:10px;padding:20px}h1{font-size:24px}.field-grid,.choice-list{grid-template-columns:1fr}.field-wide{grid-column:auto}.actions{align-items:stretch;flex-direction:column-reverse}.actions button{width:100%}.stepper{flex-wrap:nowrap;overflow:auto;padding-bottom:5px}.stepper a{white-space:nowrap}}
    </style>
</head>
<body>
<main class="contract-shell">
    <header class="contract-header"><h1>Solicitud de contrato</h1><p class="contract-subtitle">Paso {{ array_search($step, array_keys($steps), true) + 1 }} de {{ count($steps) }}: {{ $steps[$step] }}</p></header>
    <nav class="stepper" aria-label="Pasos de la solicitud">@foreach($steps as $key => $label)<a href="{{ route('contrato.solicitud.step', [$public->public_reference, $token, $key]) }}" @if($key === $step) aria-current="step" @endif>{{ $loop->iteration }}. {{ $label }}</a>@endforeach</nav>
    @if(session('success'))<p class="success">{{ session('success') }}</p>@endif @if($errors->any())<p class="alert">{{ $errors->first() }}</p>@endif
    <section class="contract-card">
