        <h2>Revisa y envía tu solicitud</h2><dl class="summary">
            <div><dt>Inmueble y uso</dt><dd>{{ data_get($payload,'leased_property.alias') }} — {{ data_get($payload,'leased_property.address') }} · {{ implode(', ', data_get($payload,'leased_property.property_use_codes',[])) }}</dd></div>
            <div><dt>Partes</dt><dd>{{ data_get($payload,'lessor.person.full_name') ?: data_get($payload,'lessor.person.legal_name') }} / {{ data_get($payload,'lessee.person.full_name') ?: data_get($payload,'lessee.person.legal_name') }}</dd></div>
            <div><dt>Tercero y garantía</dt><dd>{{ data_get($payload,'guarantor.person.full_name') ?: data_get($payload,'guarantor.person.legal_name') ?: 'Sin tercero' }} · {{ data_get($payload,'guarantee_property.exists') }} · {{ data_get($payload,'guarantee_property.address') }} · {{ data_get($payload,'guarantee_property.title_deed') }}</dd></div>
            <div><dt>Vigencia</dt><dd>{{ data_get($payload,'term.start_date') }} a {{ data_get($payload,'term.end_date') }} · {{ data_get($payload,'term.duration_label') }} · {{ data_get($payload,'term.rent_due_rule.raw_text') }}</dd></div>
            <div><dt>Importes</dt><dd>Total {{ data_get($payload,'amounts.total_rent') }}, mensual {{ data_get($payload,'amounts.monthly_rent') }}, depósito {{ data_get($payload,'amounts.security_deposit') }}, comisión {{ data_get($payload,'amounts.rental_commission') }}, mensual {{ data_get($payload,'amounts.monthly_commission_value') }} {{ data_get($payload,'amounts.monthly_commission_unit') }}</dd></div>
            <div><dt>Pago</dt><dd>{{ data_get($payload,'payment.method') }} @if(data_get($payload,'payment.method') === 'bank_transfer') — {{ data_get($payload,'payment.bank_name') }} / {{ data_get($payload,'payment.beneficiary') }} / {{ data_get($payload,'payment.clabe') }} @endif</dd></div>
            <div><dt>Mantenimiento y renovación</dt><dd>{{ data_get($payload,'maintenance.exists') }} {{ data_get($payload,'maintenance.payer') }} · {{ data_get($payload,'renewal.is_renewal') }} {{ data_get($payload,'renewal.previous_contract_id') }}</dd></div>
        </dl><p class="helper">No se genera ningún documento automáticamente.</p><form method="POST" action="{{ route('contrato.solicitud.submit', [$public->public_reference, $token]) }}" class="actions">@csrf<input type="hidden" name="website"><button class="button-primary">Enviar solicitud</button></form>
    @else
        <form method="POST" action="{{ route('contrato.solicitud.save', [$public->public_reference, $token, $step]) }}">@csrf @method('PUT')<input type="hidden" name="expected_version_id" value="{{ $draft->currentVersion->id }}"><input type="hidden" name="website">
        @if($step === 'generales')
            <h2 class="section-heading">Datos generales</h2><div class="field-grid"><label>Fecha del contrato<input type="date" name="payload[metadata][contract_date]" value="{{ data_get($payload,'metadata.contract_date') }}"></label><label>Alias del inmueble<input name="payload[leased_property][alias]" value="{{ data_get($payload,'leased_property.alias') }}"></label><label class="field-wide">Domicilio del inmueble<input name="payload[leased_property][address]" value="{{ data_get($payload,'leased_property.address') }}"></label></div>
        @elseif(in_array($step,['arrendador','arrendatario'],true))
            <h2 class="section-heading">{{ $steps[$step] }}</h2>@include('contratos.borradores._wizard_party',['party'=>$step === 'arrendador' ? 'lessor' : 'lessee','payload'=>$payload])
        @elseif($step === 'tercero')
            <h2 class="section-heading">Tercero / fiador</h2><div class="field-grid"><label>Tipo de tercero<select data-guarantor-type name="payload[guarantor][type]"><option value="none" @selected(data_get($payload,'guarantor.type') === 'none')>Sin tercero</option><option value="fisica" @selected(data_get($payload,'guarantor.type') === 'fisica')>Persona física</option><option value="moral" @selected(data_get($payload,'guarantor.type') === 'moral')>Persona moral</option></select></label></div>@include('contratos.borradores._wizard_party',['party'=>'guarantor','payload'=>$payload,'hidePartyType'=>true])
        @elseif($step === 'garantia')
            <h2 class="section-heading">Garantía</h2><div class="field-grid"><label>¿Inmueble en garantía?<select data-guarantee-exists name="payload[guarantee_property][exists]"><option value="no" @selected(data_get($payload,'guarantee_property.exists') === 'no')>No</option><option value="yes" @selected(data_get($payload,'guarantee_property.exists') === 'yes')>Sí</option></select></label><div data-conditional="guarantee-details" class="field-grid field-wide"><label>Domicilio de garantía<input name="payload[guarantee_property][address]" value="{{ data_get($payload,'guarantee_property.address') }}"></label><label>Título de propiedad<input name="payload[guarantee_property][title_deed]" value="{{ data_get($payload,'guarantee_property.title_deed') }}"></label></div></div>
        @elseif($step === 'vigencia')
            <h2 class="section-heading">Vigencia e importes</h2><div class="field-grid"><label>Fecha de inicio<input type="date" name="payload[term][start_date]" value="{{ data_get($payload,'term.start_date') }}"></label><label>Fecha de término<input type="date" name="payload[term][end_date]" value="{{ data_get($payload,'term.end_date') }}"></label><label>Duración<input name="payload[term][duration_label]" value="{{ data_get($payload,'term.duration_label') }}"></label><label>Regla de pago de renta<input name="payload[term][rent_due_rule][raw_text]" value="{{ data_get($payload,'term.rent_due_rule.raw_text') }}"></label><label>Renta total<input inputmode="decimal" name="payload[amounts][total_rent]" value="{{ data_get($payload,'amounts.total_rent') }}"></label><label>Renta mensual<input inputmode="decimal" name="payload[amounts][monthly_rent]" value="{{ data_get($payload,'amounts.monthly_rent') }}"></label><label>Depósito en garantía<input inputmode="decimal" name="payload[amounts][security_deposit]" value="{{ data_get($payload,'amounts.security_deposit') }}"></label><label>Comisión de renta<input inputmode="decimal" name="payload[amounts][rental_commission]" value="{{ data_get($payload,'amounts.rental_commission') }}"></label><label>Valor mensual de comisión<input inputmode="decimal" name="payload[amounts][monthly_commission_value]" value="{{ data_get($payload,'amounts.monthly_commission_value') }}"></label><label>Unidad de comisión mensual<select name="payload[amounts][monthly_commission_unit]">@foreach(['unknown'=>'Por definir','percent'=>'Porcentaje','fraction'=>'Fracción','fixed'=>'Fijo'] as $v=>$label)<option value="{{ $v }}" @selected(data_get($payload,'amounts.monthly_commission_unit') === $v)>{{ $label }}</option>@endforeach</select></label></div>
        @elseif($step === 'uso')
            <h2 class="section-heading">Uso del inmueble</h2><input type="hidden" name="payload[leased_property][_property_use_codes_submitted]" value="1"><div class="choice-list">@foreach(['residential'=>'Casa habitación','industrial'=>'Industrial','commercial'=>'Comercial','other'=>'Otro'] as $value=>$label)<label class="choice"><input type="checkbox" name="payload[leased_property][property_use_codes][]" value="{{ $value }}" @checked(in_array($value,data_get($payload,'leased_property.property_use_codes',[]),true))>{{ $label }}</label>@endforeach</div>
        @elseif($step === 'pago')
            <h2 class="section-heading">Forma de pago</h2><div class="field-grid"><label>Forma de pago<select data-payment-method name="payload[payment][method]"><option value="cash" @selected(data_get($payload,'payment.method') === 'cash')>Efectivo</option><option value="bank_transfer" @selected(data_get($payload,'payment.method') === 'bank_transfer')>Transferencia</option><option value="unspecified" @selected(data_get($payload,'payment.method') === 'unspecified')>Por definir</option></select></label><div data-conditional="bank-details" class="field-grid field-wide"><label>Banco<input name="payload[payment][bank_name]" value="{{ data_get($payload,'payment.bank_name') }}"></label><label>Beneficiario<input name="payload[payment][beneficiary]" value="{{ data_get($payload,'payment.beneficiary') }}"></label><label class="field-wide">CLABE<input inputmode="numeric" name="payload[payment][clabe]" value="{{ data_get($payload,'payment.clabe') }}"></label></div></div>
        @elseif($step === 'mantenimiento')
            <h2 class="section-heading">Mantenimiento</h2><div class="field-grid"><label>¿Existen cuotas de mantenimiento?<select data-maintenance-exists name="payload[maintenance][exists]"><option value="no" @selected(data_get($payload,'maintenance.exists') === 'no')>No hay cuotas</option><option value="yes" @selected(data_get($payload,'maintenance.exists') === 'yes')>Sí hay cuotas</option></select></label><label data-conditional="maintenance-payer">¿Quién cubre las cuotas?<select name="payload[maintenance][payer]"><option value="" @selected(data_get($payload,'maintenance.payer') === null)>Selecciona una opción</option><option value="lessor" @selected(data_get($payload,'maintenance.payer') === 'lessor')>Arrendador</option><option value="lessee" @selected(data_get($payload,'maintenance.payer') === 'lessee')>Arrendatario</option></select></label></div>
        @elseif($step === 'renovacion')
            <h2 class="section-heading">Renovación</h2><div class="field-grid"><label>¿Es renovación?<select data-renewal-exists name="payload[renewal][is_renewal]"><option value="no" @selected(data_get($payload,'renewal.is_renewal') === 'no')>No</option><option value="yes" @selected(data_get($payload,'renewal.is_renewal') === 'yes')>Sí</option></select></label><label data-conditional="previous-contract">Contrato previo (opcional)<input name="payload[renewal][previous_contract_id]" value="{{ data_get($payload,'renewal.previous_contract_id') }}"></label></div>
        @endif
        <div class="actions"><button type="submit" class="button-secondary">Guardar</button><button type="submit" class="button-primary" name="next" value="1">Guardar y continuar</button></div></form>
    @endif
    </section>
</main>
<script>
document.addEventListener('DOMContentLoaded',function(){
 function setVisible(element,visible){if(!element)return;element.classList.toggle('is-hidden',!visible);element.querySelectorAll('input,select,textarea').forEach(function(control){control.disabled=!visible})}
 function updateParty(party){var container=document.querySelector('[data-party-container="'+party+'"]');if(!container)return;var guarantor=document.querySelector('[data-guarantor-type]');if(party==='guarantor'&&guarantor&&guarantor.value==='none'){setVisible(container,false);return}setVisible(container,true);var type=party==='guarantor'&&guarantor?guarantor.value:(document.querySelector('[data-party-type="'+party+'"]')||{}).value;container.querySelectorAll('[data-party-branch]').forEach(function(branch){setVisible(branch,branch.dataset.type===type)})}
 function updateConditional(selector,visible){document.querySelectorAll(selector).forEach(function(element){setVisible(element,visible)})}
 function updateAll(){['lessor','lessee','guarantor'].forEach(updateParty);var guarantee=document.querySelector('[data-guarantee-exists]');updateConditional('[data-conditional="guarantee-details"]',guarantee&&guarantee.value==='yes');var payment=document.querySelector('[data-payment-method]');updateConditional('[data-conditional="bank-details"]',payment&&payment.value==='bank_transfer');var maintenance=document.querySelector('[data-maintenance-exists]');updateConditional('[data-conditional="maintenance-payer"]',maintenance&&maintenance.value==='yes');var renewal=document.querySelector('[data-renewal-exists]');updateConditional('[data-conditional="previous-contract"]',renewal&&renewal.value==='yes')}
 document.querySelectorAll('[data-party-type],[data-guarantor-type],[data-guarantee-exists],[data-payment-method],[data-maintenance-exists],[data-renewal-exists]').forEach(function(control){control.addEventListener('change',updateAll)});updateAll()
});
</script>
</body>
</html>
